@testable import RepoPromptSecureStorage
import XCTest

final class RuntimeCodeSigningPolicyTests: XCTestCase {
    func testVerifiedPersistentDomainsRouteToIsolatedServices() {
        let official = RuntimeCodeSigningInfo.synthetic(
            codeIdentifier: RuntimeCodeSigningPolicy.developerIDBundleIdentifier,
            teamIdentifier: RuntimeCodeSigningPolicy.signingTeamIdentifier,
            validatedDomains: [.developerID]
        )
        let localFingerprint = String(repeating: "A", count: 64)
        let localExpectation = RuntimeLocalSigningExpectation(
            bundleLeafCertificateSHA256: localFingerprint,
            registeredLeafCertificateSHA256: localFingerprint,
            bundleServiceGeneration: 3,
            registeredServiceGeneration: 3
        )
        let local = RuntimeCodeSigningInfo.synthetic(
            codeIdentifier: RuntimeCodeSigningPolicy.developerIDBundleIdentifier,
            leafCertificateSHA256: localFingerprint,
            validatedDomains: [.localSelfSigned]
        )
        let debug = RuntimeCodeSigningInfo.synthetic(
            codeIdentifier: RuntimeCodeSigningPolicy.appleDevelopmentDebugBundleIdentifier,
            teamIdentifier: RuntimeCodeSigningPolicy.signingTeamIdentifier,
            validatedDomains: [.appleDevelopmentDebug]
        )

        assertDecision(
            marker: "developer-id",
            debugMarker: "keychain",
            signingInfo: official,
            expectedDomain: .officialDeveloperID
        )
        assertDecision(
            marker: "local-self-signed",
            debugMarker: "keychain",
            signingInfo: local,
            localSigningContext: .valid(localExpectation),
            expectedDomain: .localSelfSigned,
            expectedLocalCertificateFingerprint: localFingerprint,
            expectedLocalServiceGeneration: 3
        )
        assertDecision(
            marker: "debug-apple-development",
            debugMarker: "keychain",
            signingInfo: debug,
            expectedDomain: .appleDevelopmentDebug,
            expectedAppleDevelopmentTeamIdentifier: RuntimeCodeSigningPolicy.signingTeamIdentifier
        )

        XCTAssertTrue(
            SecureKeyValueStorageFactory.selection(
                for: RuntimeSecureStorageDecision(domain: .officialDeveloperID, rejectionReason: nil)
            ).backend === KeychainService.officialV2Shared
        )
        let localSelection = SecureKeyValueStorageFactory.selection(
            for: RuntimeSecureStorageDecision(
                domain: .localSelfSigned,
                rejectionReason: nil,
                localCertificateFingerprint: localFingerprint,
                localServiceGeneration: 3
            )
        )
        XCTAssertEqual(
            (localSelection.backend as? KeychainService)?.serviceName,
            KeychainService.localSelfSignedServiceName(fingerprint: localFingerprint, generation: 3)
        )
        XCTAssertTrue(
            SecureKeyValueStorageFactory.selection(
                for: RuntimeSecureStorageDecision(
                    domain: .appleDevelopmentDebug,
                    rejectionReason: nil,
                    appleDevelopmentTeamIdentifier: RuntimeCodeSigningPolicy.signingTeamIdentifier
                )
            ).backend === KeychainService.debugShared
        )
    }

    func testPersonalAppleDevelopmentIdentityUsesTeamIsolatedPersistentStorage() {
        let teamIdentifier = "9S455R5DTM"
        let signingInfo = RuntimeCodeSigningInfo.synthetic(
            codeIdentifier: RuntimeCodeSigningPolicy.appleDevelopmentDebugBundleIdentifier,
            teamIdentifier: teamIdentifier,
            validatedDomains: [.appleDevelopmentDebug]
        )
        let decision = RuntimeCodeSigningPolicy.decision(
            signingModeMarker: "debug-apple-development",
            debugStorageMarker: "keychain",
            signingInfo: signingInfo
        )

        XCTAssertEqual(
            decision,
            RuntimeSecureStorageDecision(
                domain: .appleDevelopmentDebug,
                rejectionReason: nil,
                appleDevelopmentTeamIdentifier: teamIdentifier
            )
        )
        let backend = SecureKeyValueStorageFactory.selection(for: decision).backend
        XCTAssertTrue(backend.persistsValuesAcrossLaunches)
        XCTAssertEqual(
            (backend as? KeychainService)?.serviceName,
            KeychainService.appleDevelopmentDebugServiceName(teamIdentifier: teamIdentifier)
        )
        XCTAssertNotEqual(
            (backend as? KeychainService)?.serviceName,
            KeychainService.debugServiceName
        )
    }

    func testSuccessorIdentityRequiresExactMarkerAndSignaturePairing() {
        let successor = RuntimeCodeSigningInfo.synthetic(
            codeIdentifier: RuntimeCodeSigningPolicy.successorDeveloperIDBundleIdentifier,
            teamIdentifier: RuntimeCodeSigningPolicy.successorSigningTeamIdentifier,
            validatedDomains: [.successorDeveloperID]
        )
        let legacy = RuntimeCodeSigningInfo.synthetic(
            codeIdentifier: RuntimeCodeSigningPolicy.developerIDBundleIdentifier,
            teamIdentifier: RuntimeCodeSigningPolicy.signingTeamIdentifier,
            validatedDomains: [.developerID]
        )

        assertDecision(
            marker: "successor-developer-id",
            debugMarker: nil,
            signingInfo: successor,
            expectedDomain: .successorOfficialDeveloperID
        )

        // Cross-pairings between markers and signatures must fail closed.
        let mismatches: [(String, RuntimeCodeSigningInfo)] = [
            ("successor-developer-id", legacy),
            ("developer-id", successor),
            ("successor-developer-id", RuntimeCodeSigningInfo.synthetic(
                codeIdentifier: RuntimeCodeSigningPolicy.successorDeveloperIDBundleIdentifier,
                teamIdentifier: RuntimeCodeSigningPolicy.signingTeamIdentifier,
                validatedDomains: [.successorDeveloperID]
            )),
            ("successor-developer-id", RuntimeCodeSigningInfo.synthetic(
                codeIdentifier: RuntimeCodeSigningPolicy.successorDeveloperIDBundleIdentifier,
                teamIdentifier: RuntimeCodeSigningPolicy.successorSigningTeamIdentifier,
                validatedDomains: [.developerID]
            )),
            ("successor-developer-id", RuntimeCodeSigningInfo.synthetic(
                codeIdentifier: RuntimeCodeSigningPolicy.successorDeveloperIDBundleIdentifier,
                teamIdentifier: RuntimeCodeSigningPolicy.successorSigningTeamIdentifier,
                isAdHoc: true,
                validatedDomains: [.successorDeveloperID]
            ))
        ]
        for (marker, signingInfo) in mismatches {
            assertDecision(
                marker: marker,
                debugMarker: nil,
                signingInfo: signingInfo,
                expectedDomain: .ephemeral,
                expectedReason: .markerSignatureMismatch
            )
        }
    }

    func testSuccessorDomainStaysEphemeralUntilBridgeOverrideAndAcceptsOverride() {
        let decision = RuntimeSecureStorageDecision(
            domain: .successorOfficialDeveloperID,
            rejectionReason: nil
        )

        // Without a committed-bridge override the successor identity must not
        // fall back to the legacy Keychain service.
        XCTAssertTrue(
            SecureKeyValueStorageFactory.selection(for: decision).backend === EphemeralSecureKeyValueStore.shared
        )

        XCTAssertTrue(SecureKeyValueStorageFactory.officialOverrideApplies(to: .officialDeveloperID))
        XCTAssertTrue(SecureKeyValueStorageFactory.officialOverrideApplies(to: .successorOfficialDeveloperID))
        XCTAssertFalse(SecureKeyValueStorageFactory.officialOverrideApplies(to: .localSelfSigned))
        XCTAssertFalse(SecureKeyValueStorageFactory.officialOverrideApplies(to: .appleDevelopmentDebug))
        XCTAssertFalse(SecureKeyValueStorageFactory.officialOverrideApplies(to: .ephemeral))
    }

    func testRejectedModesExhaustivelyFailClosedToEphemeralStorage() {
        let official = RuntimeCodeSigningInfo.synthetic(
            codeIdentifier: RuntimeCodeSigningPolicy.developerIDBundleIdentifier,
            teamIdentifier: RuntimeCodeSigningPolicy.signingTeamIdentifier,
            validatedDomains: [.developerID]
        )
        let debug = RuntimeCodeSigningInfo.synthetic(
            codeIdentifier: RuntimeCodeSigningPolicy.appleDevelopmentDebugBundleIdentifier,
            teamIdentifier: RuntimeCodeSigningPolicy.signingTeamIdentifier,
            validatedDomains: [.appleDevelopmentDebug]
        )
        let invalid = RuntimeCodeSigningInfo.synthetic(failure: .signatureInvalid)

        let cases: [(String?, String?, RuntimeCodeSigningInfo, RuntimeSecureStorageRejectionReason)] = [
            (nil, nil, official, .missingSigningModeMarker),
            ("", nil, official, .missingSigningModeMarker),
            ("unknown", nil, official, .unknownSigningModeMarker),
            ("release-candidate-adhoc", nil, official, .releaseCandidate),
            ("debug-adhoc", "alternate-in-memory", debug, .adHocDebug),
            ("debug-apple-development", "alternate-in-memory", debug, .debugEphemeralRequested),
            ("debug-apple-development", nil, debug, .missingDebugStorageMarker),
            ("debug-apple-development", "unknown", debug, .unknownDebugStorageMarker),
            ("developer-id", nil, invalid, .signingValidationFailed),
            ("developer-id", nil, debug, .markerSignatureMismatch),
            ("local-self-signed", nil, official, .localIdentityRegistryUnavailable),
            ("debug-apple-development", "keychain", official, .markerSignatureMismatch),
            ("developer-id", nil, RuntimeCodeSigningInfo.synthetic(
                codeIdentifier: RuntimeCodeSigningPolicy.developerIDBundleIdentifier,
                teamIdentifier: RuntimeCodeSigningPolicy.signingTeamIdentifier,
                isAdHoc: true,
                validatedDomains: [.developerID]
            ), .markerSignatureMismatch)
        ]

        for (marker, debugMarker, signingInfo, expectedReason) in cases {
            let decision = RuntimeCodeSigningPolicy.decision(
                signingModeMarker: marker,
                debugStorageMarker: debugMarker,
                signingInfo: signingInfo
            )
            XCTAssertEqual(decision, RuntimeSecureStorageDecision(domain: .ephemeral, rejectionReason: expectedReason))
            XCTAssertTrue(SecureKeyValueStorageFactory.selection(for: decision).backend === EphemeralSecureKeyValueStore.shared)
        }
    }

    func testPersistentDomainsRequireExactIdentifierAndTeam() {
        let wrongIdentifier = RuntimeCodeSigningInfo.synthetic(
            codeIdentifier: "com.example.other",
            teamIdentifier: RuntimeCodeSigningPolicy.signingTeamIdentifier,
            validatedDomains: [.developerID]
        )
        let wrongTeam = RuntimeCodeSigningInfo.synthetic(
            codeIdentifier: RuntimeCodeSigningPolicy.developerIDBundleIdentifier,
            teamIdentifier: "OTHERTEAM",
            validatedDomains: [.developerID]
        )

        for signingInfo in [wrongIdentifier, wrongTeam] {
            assertDecision(
                marker: "developer-id",
                debugMarker: nil,
                signingInfo: signingInfo,
                expectedDomain: .ephemeral,
                expectedReason: .markerSignatureMismatch
            )
        }
    }

    func testLocalSigningExpectationRequiresMatchingFingerprintAndGeneration() {
        let fingerprint = String(repeating: "AB", count: 32)
        XCTAssertEqual(
            RuntimeLocalSigningExpectation(
                bundleLeafCertificateSHA256: fingerprint.lowercased(),
                registeredLeafCertificateSHA256: fingerprint,
                bundleServiceGeneration: 4,
                registeredServiceGeneration: 4
            ).validatedIdentity,
            RuntimeValidatedLocalSigningIdentity(fingerprint: fingerprint, serviceGeneration: 4)
        )
        XCTAssertNil(
            RuntimeLocalSigningExpectation(
                bundleLeafCertificateSHA256: fingerprint,
                registeredLeafCertificateSHA256: String(repeating: "CD", count: 32),
                bundleServiceGeneration: 4,
                registeredServiceGeneration: 4
            ).validatedIdentity
        )
        XCTAssertNil(
            RuntimeLocalSigningExpectation(
                bundleLeafCertificateSHA256: fingerprint,
                registeredLeafCertificateSHA256: fingerprint,
                bundleServiceGeneration: 4,
                registeredServiceGeneration: 5
            ).validatedIdentity
        )
    }

    func testLocalPersistenceFailsClosedWithoutMatchingRegistryContext() {
        let fingerprint = String(repeating: "A", count: 64)
        let signingInfo = RuntimeCodeSigningInfo.synthetic(
            codeIdentifier: RuntimeCodeSigningPolicy.developerIDBundleIdentifier,
            leafCertificateSHA256: fingerprint,
            validatedDomains: [.localSelfSigned]
        )

        let rejectedContexts: [(RuntimeLocalSigningContext, RuntimeSecureStorageRejectionReason)] = [
            (.invalid(.localIdentityMetadataUnavailable), .localIdentityMetadataUnavailable),
            (.invalid(.localIdentityRegistryUnavailable), .localIdentityRegistryUnavailable),
            (.invalid(.localIdentityContinuityMismatch), .localIdentityContinuityMismatch)
        ]
        for (context, reason) in rejectedContexts {
            assertDecision(
                marker: "local-self-signed",
                debugMarker: "keychain",
                signingInfo: signingInfo,
                localSigningContext: context,
                expectedDomain: .ephemeral,
                expectedReason: reason
            )
        }
    }

    func testCompileTimeTrustAnchorsIncludeExpectedCertificateClasses() {
        XCTAssertEqual(RuntimeCodeSigningPolicy.developerIDBundleIdentifier, "com.pvncher.repoprompt.ce")
        XCTAssertEqual(RuntimeCodeSigningPolicy.appleDevelopmentDebugBundleIdentifier, "com.repoprompt.ce.debug")
        XCTAssertEqual(RuntimeCodeSigningPolicy.signingTeamIdentifier, "648A27MST5")
        XCTAssertEqual(RuntimeCodeSigningPolicy.successorDeveloperIDBundleIdentifier, "com.repoprompt.ce")
        XCTAssertEqual(RuntimeCodeSigningPolicy.successorSigningTeamIdentifier, "69N6K965SF")
        XCTAssertTrue(RuntimeCodeSigningPolicy.developerIDRequirement.contains("1.2.840.113635.100.6.1.13"))
        XCTAssertTrue(RuntimeCodeSigningPolicy.appleDevelopmentDebugRequirement.contains("1.2.840.113635.100.6.1.12"))
        XCTAssertTrue(RuntimeCodeSigningPolicy.successorDeveloperIDRequirement.contains("1.2.840.113635.100.6.1.13"))
        XCTAssertEqual(
            RuntimeCodeSigningPolicy.successorDeveloperIDRequirement,
            "anchor apple generic and identifier \"com.repoprompt.ce\" and certificate leaf[subject.OU] = \"69N6K965SF\" and certificate leaf[field.1.2.840.113635.100.6.1.13] exists"
        )
    }

    private func assertDecision(
        marker: String?,
        debugMarker: String?,
        signingInfo: RuntimeCodeSigningInfo,
        localSigningContext: RuntimeLocalSigningContext? = nil,
        expectedDomain: RuntimeSecureStorageDomain,
        expectedReason: RuntimeSecureStorageRejectionReason? = nil,
        expectedLocalCertificateFingerprint: String? = nil,
        expectedLocalServiceGeneration: Int? = nil,
        expectedAppleDevelopmentTeamIdentifier: String? = nil
    ) {
        XCTAssertEqual(
            RuntimeCodeSigningPolicy.decision(
                signingModeMarker: marker,
                debugStorageMarker: debugMarker,
                signingInfo: signingInfo,
                localSigningContext: localSigningContext
            ),
            RuntimeSecureStorageDecision(
                domain: expectedDomain,
                rejectionReason: expectedReason,
                localCertificateFingerprint: expectedLocalCertificateFingerprint,
                localServiceGeneration: expectedLocalServiceGeneration,
                appleDevelopmentTeamIdentifier: expectedAppleDevelopmentTeamIdentifier
            )
        )
    }
}

import Foundation
@testable import RepoPromptApp
import RepoPromptSecureStorage
import XCTest

final class JevRouterCredentialServiceTests: XCTestCase {
    func testLateValidationCannotOverwriteNewerCandidate() async {
        let storage = TestSecureStorageBackend()
        let client = ControlledJevClient()
        let service = JevRouterCredentialService(
            secureKeys: SecureKeysService(secureStorage: storage),
            client: client
        )
        let firstID = UUID()
        let secondID = UUID()
        let first = Task { await service.validateAndSave("candidate-a", operationID: firstID) }
        await client.waitUntilStarted("candidate-a")
        let second = Task { await service.validateAndSave("candidate-b", operationID: secondID) }
        await client.waitUntilStarted("candidate-b")

        await client.complete("candidate-b")
        guard case .saved = await second.value else { return XCTFail("Newer candidate did not save") }
        await client.complete("candidate-a")
        let firstResult = await first.value
        XCTAssertEqual(firstResult, .superseded)
        XCTAssertEqual(storage.value(for: .jevRouterAPIKey), "candidate-b")
    }

    func testStoredKeyUsesExplicitNoninteractiveAccessMode() async {
        let storage = TestSecureStorageBackend(values: [.jevRouterAPIKey: "stored"])
        let client = ImmediateJevClient()
        let service = JevRouterCredentialService(
            secureKeys: SecureKeysService(secureStorage: storage),
            client: client
        )
        _ = await service.validateStoredKey(
            operationID: UUID(),
            accessMode: .nonInteractive(reason: .backgroundAvailabilityCheck)
        )
        XCTAssertTrue(storage.calls.contains(.init(
            operation: .get,
            account: .jevRouterAPIKey,
            accessMode: .nonInteractive(reason: .backgroundAvailabilityCheck)
        )))
        guard case let .ready(_, policyVersion) = await service.readinessSnapshot() else {
            return XCTFail("A valid key must make Jev ready")
        }
        XCTAssertEqual(policyVersion, JevRouterCredentialService.routingPolicyVersion)
    }

    func testSavedKeyBootstrapsAReplacementServiceInstance() async {
        let storage = TestSecureStorageBackend()
        let first = JevRouterCredentialService(
            secureKeys: SecureKeysService(secureStorage: storage),
            client: ImmediateJevClient()
        )
        guard case .saved = await first.validateAndSave("persistent", operationID: UUID()) else {
            return XCTFail("Expected the first service to save the key")
        }

        let replacement = JevRouterCredentialService(
            secureKeys: SecureKeysService(secureStorage: storage),
            client: ImmediateJevClient()
        )
        await replacement.bootstrapStoredConfigurationIfNeeded()

        guard case .ready = await replacement.readinessSnapshot() else {
            return XCTFail("A replacement service must restore readiness from persisted storage")
        }
    }

    func testMissingStoredKeyInvalidatesPreviouslyValidatedReadiness() async throws {
        let storage = TestSecureStorageBackend(values: [.jevRouterAPIKey: "stored"])
        let service = JevRouterCredentialService(
            secureKeys: SecureKeysService(secureStorage: storage),
            client: ImmediateJevClient()
        )
        guard case .saved = await service.validateStoredKey(operationID: UUID()) else {
            return XCTFail("Expected initial stored-key validation")
        }
        try storage.delete(for: SecureStorageAccount.jevRouterAPIKey.identifier, accessMode: .interactive)

        let result = await service.validateStoredKey(operationID: UUID())
        XCTAssertEqual(result, .missingKey)
        guard case .needsConfiguration = await service.readinessSnapshot() else {
            return XCTFail("Missing stored credential must fail closed")
        }
    }

    func testReadinessGenerationPublishesToTwoWindowObservers() async {
        let service = JevRouterCredentialService(
            secureKeys: SecureKeysService(secureStorage: TestSecureStorageBackend(values: [.jevRouterAPIKey: "stored"])),
            client: ImmediateJevClient()
        )
        let firstStream = await service.readinessUpdates()
        let secondStream = await service.readinessUpdates()
        let first = Task { await firstStream.firstReadyGeneration() }
        let second = Task { await secondStream.firstReadyGeneration() }
        await service.bootstrapStoredConfigurationIfNeeded()
        let firstGeneration = await first.value
        let secondGeneration = await second.value
        XCTAssertNotNil(firstGeneration)
        XCTAssertEqual(firstGeneration, secondGeneration)
    }

    func testCancelValidationCancelsExactTransportTask() async {
        let client = CancellationObservingJevClient()
        let service = JevRouterCredentialService(client: client)
        let validation = Task { await service.validateAndSave("candidate", operationID: UUID()) }
        await client.waitUntilStarted()
        await service.cancelAndAdvanceGeneration()
        let validationResult = await validation.value
        XCTAssertEqual(validationResult, .superseded)
        await client.waitUntilCancelled()
        guard case let .needsConfiguration(generation, _) = await service.readinessSnapshot() else {
            return XCTFail("Cancellation must advance generation and fail closed")
        }
        XCTAssertGreaterThan(generation, 0)
    }

    func testCancelValidationSettlesWhenClientIgnoresCancellationAndFiltersLateSuccess() async {
        let storage = TestSecureStorageBackend()
        let client = ControlledJevClient()
        let service = JevRouterCredentialService(
            secureKeys: SecureKeysService(secureStorage: storage),
            client: client
        )
        let validation = Task { await service.validateAndSave("candidate", operationID: UUID()) }
        await client.waitUntilStarted("candidate")

        await service.cancelAndAdvanceGeneration()
        let result = await validation.value
        XCTAssertEqual(result, .superseded)
        await client.complete("candidate")
        await Task.yield()

        XCTAssertNil(storage.value(for: .jevRouterAPIKey))
        guard case .needsConfiguration = await service.readinessSnapshot() else {
            return XCTFail("Late success must not republish validated readiness")
        }
    }
}

private extension AsyncStream where Element == DecisionReadiness {
    func firstReadyGeneration() async -> UInt64? {
        for await readiness in self {
            if case let .ready(generation, _) = readiness { return generation }
        }
        return nil
    }
}

private actor ControlledJevClient: JevRoutingClientProtocol {
    private var started: Set<String> = []
    private var startWaiters: [String: [CheckedContinuation<Void, Never>]] = [:]
    private var completions: [String: CheckedContinuation<JevModelList, Error>] = [:]

    func listModels(apiKey: String, timeout: Duration) async throws -> JevModelList {
        started.insert(apiKey)
        startWaiters.removeValue(forKey: apiKey)?.forEach { $0.resume() }
        return try await withCheckedThrowingContinuation { completions[apiKey] = $0 }
    }

    func judge(
        request: JevRoutingWireRequest,
        apiKey: String,
        timeout: Duration
    ) async throws -> JevRoutingWireResponse {
        throw JevRoutingClientError.invalidRequest
    }

    func waitUntilStarted(_ key: String) async {
        if started.contains(key) { return }
        await withCheckedContinuation { startWaiters[key, default: []].append($0) }
    }

    func complete(_ key: String) {
        completions.removeValue(forKey: key)?.resume(returning: .init(models: [.init(name: "jev")]))
    }
}

private struct ImmediateJevClient: JevRoutingClientProtocol {
    func listModels(apiKey: String, timeout: Duration) async throws -> JevModelList {
        .init(models: [.init(name: "jev-latest")])
    }

    func judge(
        request: JevRoutingWireRequest,
        apiKey: String,
        timeout: Duration
    ) async throws -> JevRoutingWireResponse {
        throw JevRoutingClientError.invalidRequest
    }
}

private actor CancellationObservingJevClient: JevRoutingClientProtocol {
    private var started = false
    private var cancelled = false
    private var startWaiters: [CheckedContinuation<Void, Never>] = []
    private var cancellationWaiters: [CheckedContinuation<Void, Never>] = []

    func listModels(apiKey: String, timeout: Duration) async throws -> JevModelList {
        started = true
        startWaiters.forEach { $0.resume() }
        startWaiters.removeAll()
        do {
            try await Task.sleep(for: .seconds(60))
            throw JevRoutingClientError.timeout
        } catch is CancellationError {
            cancelled = true
            cancellationWaiters.forEach { $0.resume() }
            cancellationWaiters.removeAll()
            throw CancellationError()
        }
    }

    func judge(request: JevRoutingWireRequest, apiKey: String, timeout: Duration) async throws -> JevRoutingWireResponse {
        throw JevRoutingClientError.invalidRequest
    }

    func waitUntilStarted() async {
        if started { return }
        await withCheckedContinuation { startWaiters.append($0) }
    }

    func waitUntilCancelled() async {
        if cancelled { return }
        await withCheckedContinuation { cancellationWaiters.append($0) }
    }
}

final class OpenAIDecisionsRouterCredentialServiceTests: XCTestCase {
    func testSyntheticValidationSavesOnlyDedicatedAccountInteractively() async {
        let storage = TestSecureStorageBackend(values: [.openAIAPI: "provider", .codexCLIAPI: "cli", .jevRouterAPIKey: "jev"])
        let recorder = DecisionsTestRecorder()
        let service = makeService(storage, recorder)
        let result = await service.validateAndSave(" candidate ", operationID: UUID())
        XCTAssertEqual(result, .saved(generation: 1))
        XCTAssertEqual(storage.value(for: .openAIDecisionsRouterAPIKey), "candidate")
        XCTAssertEqual(storage.value(for: .openAIAPI), "provider")
        let requests = await recorder.requests
        XCTAssertEqual(requests, [OpenAIDecisionsRouterCredentialService.validationRequest])
        XCTAssertEqual(storage.calls, [.init(operation: .save, account: .openAIDecisionsRouterAPIKey, accessMode: .interactive)])
    }

    func testMissingKeyAndKeychainDenialAreDistinct() async {
        let storage = TestSecureStorageBackend()
        let service = makeService(storage)
        let missing = await service.validateStoredKey(operationID: UUID())
        XCTAssertEqual(missing, .missingKey)
        storage.getErrors[.openAIDecisionsRouterAPIKey] = .interactionNotAllowed
        let denied = await service.validateStoredKey(operationID: UUID())
        guard case .failed = denied else { return XCTFail("Expected redacted storage failure") }
        let state = await service.readinessSnapshot()
        guard case .temporarilyUnavailable = state else { return XCTFail("Denial is not a missing key") }
    }

    func testBootstrapAndRoutingUseNoninteractiveAccessRevalidationUsesInteractive() async throws {
        let storage = TestSecureStorageBackend(values: [.openAIDecisionsRouterAPIKey: "stored"])
        let service = makeService(storage)
        await service.bootstrapStoredConfigurationIfNeeded()
        _ = try await service.judgeForRouting(OpenAIDecisionsRouterCredentialService.validationRequest)
        _ = await service.perform(.revalidateStoredSecret)
        XCTAssertEqual(storage.calls.map(\.accessMode), [.nonInteractive(reason: .backgroundAvailabilityCheck), .nonInteractive(reason: .backgroundAvailabilityCheck), .interactive])
    }

    func testFailedBootstrapDoesNotRebillSameGeneration() async {
        let recorder = DecisionsTestRecorder(error: .timeout)
        let service = makeService(TestSecureStorageBackend(values: [.openAIDecisionsRouterAPIKey: "stored"]), recorder)
        await service.bootstrapStoredConfigurationIfNeeded()
        await service.bootstrapStoredConfigurationIfNeeded()
        let count = await recorder.requests.count
        XCTAssertEqual(count, 1)
        _ = await service.validateStoredKey(operationID: UUID())
        let explicitCount = await recorder.requests.count
        XCTAssertEqual(explicitCount, 2)
    }

    func testBootstrapSkipsExplicitValidationAtomically() async {
        let gate = DecisionsTestGate()
        let service = OpenAIDecisionsRouterCredentialService(secureKeys: SecureKeysService(secureStorage: TestSecureStorageBackend()), decide: { request, key in try await gate.decide(request, key: key) })
        let operation = Task { await service.validateAndSave("candidate", operationID: UUID()) }
        await gate.waitFor("candidate")
        await service.bootstrapStoredConfigurationIfNeeded()
        let count = await gate.count
        XCTAssertEqual(count, 1)
        await gate.complete("candidate")
        _ = await operation.value
    }

    func testFailedReplacementRestoresStableReadyNotValidating() async {
        let recorder = DecisionsTestRecorder()
        let service = makeService(TestSecureStorageBackend(), recorder)
        _ = await service.validateAndSave("old", operationID: UUID())
        let before = await service.readinessSnapshot()
        await recorder.setError(.policyUnavailable)
        _ = await service.validateAndSave("bad", operationID: UUID())
        let after = await service.readinessSnapshot()
        XCTAssertEqual(after, before)
    }

    func testOverlappingReplacementsCancelPromptlyAndLateResultCannotSave() async {
        let storage = TestSecureStorageBackend()
        let gate = DecisionsTestGate()
        let service = OpenAIDecisionsRouterCredentialService(secureKeys: SecureKeysService(secureStorage: storage), decide: { request, key in try await gate.decide(request, key: key) })
        let first = Task { await service.validateAndSave("first", operationID: UUID()) }
        await gate.waitFor("first")
        let second = Task { await service.validateAndSave("second", operationID: UUID()) }
        await gate.waitFor("second")
        // Fake deliberately ignores cancellation; logical caller must settle before fake completes.
        let result = await first.value
        XCTAssertEqual(result, .superseded)
        await gate.complete("second")
        _ = await second.value
        await gate.complete("first")
        XCTAssertEqual(storage.value(for: .openAIDecisionsRouterAPIKey), "second")
        let state = await service.readinessSnapshot()
        XCTAssertEqual(state.generation, 1)
