        XCTAssertEqual(
            encoded,
            #"{"attemptIdentifier":"123e4567-e89b-12d3-a456-426614174000","catalogIdentifiers":["AnthropicAPI","OpenAIAPI"],"status":"committed","version":2}"#
        )
