            fake_codex = root / "fake-codex"
            script_template = """#!/usr/bin/env python3
import json
import pathlib
import sys

marker = pathlib.Path(%s)
if sys.argv[1:] == ["--version"]:
    print(%s)
    raise SystemExit(0)
marker.write_text(json.dumps(sys.argv[1:]), encoding="utf-8")
out = pathlib.Path(sys.argv[sys.argv.index("--out") + 1])
out.mkdir(parents=True, exist_ok=True)
(out / "ClientNotification.json").write_text(json.dumps({
    "oneOf": [{
        "type": "object",
        "required": ["method"],
        "properties": {"method": {"const": "initialized"}}
    }]
}), encoding="utf-8")
"""
            fake_codex.write_text(
                script_template % (repr(str(marker)), repr("codex-cli 0.156.1")),
                encoding="utf-8",
            )
            fake_codex.chmod(0o755)
            contract_path = root / "contract.json"
            contract_path.write_text(
                json.dumps(
                    contract([
                        {"union": "ClientNotification.json", "method": "initialized"}
                    ])
                ),
                encoding="utf-8",
            )

            stdout = io.StringIO()
            stderr = io.StringIO()
            with contextlib.redirect_stdout(stdout), contextlib.redirect_stderr(stderr):
