import Foundation

package struct BundleIdentityDefaultsMigrationReport: Equatable {
    package enum Outcome: String {
        case skipped
        case alreadyCompleted = "already-completed"
        case migrated
        case verificationFailed = "verification-failed"
    }

    package let outcome: Outcome
    package let copiedKeyCount: Int
    package let preservedKeyCount: Int
}

/// Moves the legacy application preference domain to the successor bundle ID once.
/// Existing successor values always win, including Sparkle and window-state values.
package enum BundleIdentityDefaultsMigration {
    package static let completionMarker = "RepoPromptIdentityDefaultsMigrationV1Completed"

    package static func migrateIfNeeded(
        bundleIdentifier: String? = Bundle.main.bundleIdentifier,
        defaults: UserDefaults = .standard,
        legacyDomainName: String = RuntimeCodeSigningPolicy.developerIDBundleIdentifier,
        successorDomainName: String = RuntimeCodeSigningPolicy.successorDeveloperIDBundleIdentifier
    ) -> BundleIdentityDefaultsMigrationReport {
        guard bundleIdentifier == RuntimeCodeSigningPolicy.successorDeveloperIDBundleIdentifier else {
            return BundleIdentityDefaultsMigrationReport(
                outcome: .skipped,
                copiedKeyCount: 0,
                preservedKeyCount: 0
            )
        }

        let successorDomain = defaults.persistentDomain(forName: successorDomainName) ?? [:]
        if successorDomain[completionMarker] as? Bool == true {
            return BundleIdentityDefaultsMigrationReport(
                outcome: .alreadyCompleted,
                copiedKeyCount: 0,
                preservedKeyCount: successorDomain.count
            )
        }

        let legacyDomain = defaults.persistentDomain(forName: legacyDomainName) ?? [:]
        var mergedDomain = legacyDomain
        mergedDomain.removeValue(forKey: completionMarker)
        for (key, value) in successorDomain {
            mergedDomain[key] = value
        }
        mergedDomain[completionMarker] = true

        let copiedKeyCount = legacyDomain.keys.count(where: {
            $0 != completionMarker && successorDomain[$0] == nil
        })
        let preservedKeyCount = successorDomain.keys.count(where: { $0 != completionMarker })

        defaults.setPersistentDomain(mergedDomain, forName: successorDomainName)
        let persistedDomain = defaults.persistentDomain(forName: successorDomainName) ?? [:]
        guard domainsMatch(expected: mergedDomain, actual: persistedDomain) else {
            return BundleIdentityDefaultsMigrationReport(
                outcome: .verificationFailed,
                copiedKeyCount: copiedKeyCount,
                preservedKeyCount: preservedKeyCount
            )
        }

        return BundleIdentityDefaultsMigrationReport(
            outcome: .migrated,
            copiedKeyCount: copiedKeyCount,
            preservedKeyCount: preservedKeyCount
        )
    }

    private static func domainsMatch(expected: [String: Any], actual: [String: Any]) -> Bool {
        NSDictionary(dictionary: expected).isEqual(to: actual)
    }
}

import Foundation

package enum SecureStorageRepairFailure: Equatable {
    case authenticationFailed
    case invalidData
    case keychainFailure
    case verificationFailed
    case confirmationRequired
}

package enum SecureStorageRepairState: Equatable {
    case absent
    case importable
    case interactionRequired
    case imported
    case conflict
    case cancelled
    case failed(SecureStorageRepairFailure)
}

package struct SecureStorageRepairRecord: Equatable, Identifiable {
    package let account: SecureStorageAccount
    package let state: SecureStorageRepairState
    package let targetVerified: Bool

    package var id: String {
        account.identifier
    }

    package var legacyDeletionAvailable: Bool {
        state == .imported && targetVerified
    }
}

package enum SecureStorageConflictResolution {
    case preserveTarget
    case replaceTarget
}

package actor SecureStorageRepairService {
    private let accounts: [SecureStorageAccount]
    private let legacyStore: SecureKeyValueStorageBackend
    private let targetStore: SecureKeyValueStorageBackend

    package init(
        accounts: [SecureStorageAccount] = SecureStorageAccountCatalog.allAccounts,
        legacyStore: SecureKeyValueStorageBackend,
        targetStore: SecureKeyValueStorageBackend
    ) {
        self.accounts = accounts
        self.legacyStore = legacyStore
        self.targetStore = targetStore
    }

    package static func makeForCurrentRuntime() -> SecureStorageRepairService? {
        makeForRuntime(
            decision: SecureKeyValueStorageFactory.currentDecision(),
            legacyStore: KeychainService.legacyRepairSource(),
            targetStore: SecureKeyValueStorageFactory.defaultBackend()
        )
    }

    static func makeForRuntime(
        decision: RuntimeSecureStorageDecision,
        legacyStore: SecureKeyValueStorageBackend,
        targetStore: SecureKeyValueStorageBackend
    ) -> SecureStorageRepairService? {
        guard decision.domain == .officialDeveloperID else { return nil }
        return SecureStorageRepairService(legacyStore: legacyStore, targetStore: targetStore)
    }

    package func scan() -> [SecureStorageRepairRecord] {
        accounts.map(scanAccount)
    }

    package func importAccount(
        _ account: SecureStorageAccount,
        resolution: SecureStorageConflictResolution = .preserveTarget
    ) -> SecureStorageRepairRecord {
        let legacyValue: String
        do {
            legacyValue = try legacyStore.get(for: account.identifier, accessMode: .interactive)
        } catch {
            return record(account, for: error)
        }

        do {
            let targetValue = try targetStore.get(for: account.identifier, accessMode: .interactive)
            if targetValue == legacyValue {
                return importedRecord(account)
            }
            guard resolution == .replaceTarget else {
                return SecureStorageRepairRecord(account: account, state: .conflict, targetVerified: false)
            }
        } catch KeychainService.KeychainError.itemNotFound {
            // The target will be created below.
        } catch {
            return record(account, for: error)
        }

        do {
            try targetStore.save(legacyValue, for: account.identifier, accessMode: .interactive)
            let verifiedValue = try targetStore.get(for: account.identifier, accessMode: .interactive)
            guard verifiedValue == legacyValue else {
                return failedRecord(account, .verificationFailed)
            }
            return importedRecord(account)
        } catch {
            return record(account, for: error)
        }
    }

    package func deleteLegacy(
        _ account: SecureStorageAccount,
        confirmed: Bool
    ) -> SecureStorageRepairRecord {
        guard confirmed else {
            return failedRecord(account, .confirmationRequired)
        }

        let legacyValue: String
        let targetValue: String
        do {
            legacyValue = try legacyStore.get(for: account.identifier, accessMode: .interactive)
            targetValue = try targetStore.get(for: account.identifier, accessMode: .interactive)
        } catch {
            return record(account, for: error)
        }

        guard legacyValue == targetValue else {
            return SecureStorageRepairRecord(account: account, state: .conflict, targetVerified: false)
        }

        do {
            try legacyStore.delete(for: account.identifier, accessMode: .interactive)
            do {
                _ = try legacyStore.get(for: account.identifier, accessMode: .interactive)
                return failedRecord(account, .verificationFailed)
            } catch KeychainService.KeychainError.itemNotFound {
                return SecureStorageRepairRecord(account: account, state: .absent, targetVerified: true)
            } catch {
                return record(account, for: error)
            }
        } catch {
            return record(account, for: error)
        }
    }

    private func scanAccount(_ account: SecureStorageAccount) -> SecureStorageRepairRecord {
        let accessMode = KeychainAccessMode.nonInteractive(reason: .backgroundAvailabilityCheck)
        let legacyValue: String
        do {
            legacyValue = try legacyStore.get(for: account.identifier, accessMode: accessMode)
        } catch {
            return record(account, for: error)
        }

        do {
            let targetValue = try targetStore.get(for: account.identifier, accessMode: accessMode)
            if targetValue == legacyValue {
                return importedRecord(account)
            }
            return SecureStorageRepairRecord(account: account, state: .conflict, targetVerified: false)
        } catch KeychainService.KeychainError.itemNotFound {
            return SecureStorageRepairRecord(account: account, state: .importable, targetVerified: false)
        } catch {
            return record(account, for: error)
        }
    }

    private func record(_ account: SecureStorageAccount, for error: Error) -> SecureStorageRepairRecord {
        let state: SecureStorageRepairState = switch error {
        case KeychainService.KeychainError.itemNotFound:
            .absent
        case KeychainService.KeychainError.interactionNotAllowed:
            .interactionRequired
        case KeychainService.KeychainError.userInteractionCancelled:
            .cancelled
        case KeychainService.KeychainError.authenticationFailed:
            .failed(.authenticationFailed)
        case KeychainService.KeychainError.invalidData:
            .failed(.invalidData)
        default:
            .failed(.keychainFailure)
        }
        return SecureStorageRepairRecord(account: account, state: state, targetVerified: false)
    }

    private func importedRecord(_ account: SecureStorageAccount) -> SecureStorageRepairRecord {
        SecureStorageRepairRecord(account: account, state: .imported, targetVerified: true)
    }

    private func failedRecord(
        _ account: SecureStorageAccount,
        _ failure: SecureStorageRepairFailure
    ) -> SecureStorageRepairRecord {
        SecureStorageRepairRecord(account: account, state: .failed(failure), targetVerified: false)
    }
}

import Foundation

struct DecisionServiceCapabilities: Equatable {
    struct FiniteChoice: Equatable {
        let minimumChoices: Int
        let maximumChoices: Int
        let maximumContextBytes: Int
        let maximumInstructionsBytes: Int
        let maximumChoiceDescriptionBytes: Int
        let maximumAggregateBytes: Int
    }

    struct Evidence: Equatable {
        let confidence: Bool
        let probabilityDistribution: Bool
        let usage: Bool
    }

    enum ContextKind: Hashable { case text }

    let contextKinds: Set<ContextKind>
    let finiteChoice: FiniteChoice
    let evidence: Evidence

    func supports(_ requirement: DecisionCapabilityRequirement, request: FiniteChoiceDecisionRequest) -> Bool {
        guard contextKinds.contains(requirement.contextKind),
              !requirement.requiresConfidence || evidence.confidence,
              !requirement.requiresProbabilities || evidence.probabilityDistribution,
              !requirement.requiresUsage || evidence.usage
        else { return false }
        let count = request.question.choices.count
        return count >= finiteChoice.minimumChoices
            && count <= finiteChoice.maximumChoices
            && request.textContext.utf8.count <= finiteChoice.maximumContextBytes
            && request.question.instructions.utf8.count <= finiteChoice.maximumInstructionsBytes
            && request.question.choices.allSatisfy {
                $0.description.utf8.count <= finiteChoice.maximumChoiceDescriptionBytes
            }
            && request.aggregateUTF8Bytes <= finiteChoice.maximumAggregateBytes
    }

    var isValid: Bool {
        contextKinds.contains(.text)
            && finiteChoice.minimumChoices >= 2
            && finiteChoice.maximumChoices >= finiteChoice.minimumChoices
            && finiteChoice.maximumContextBytes > 0
            && finiteChoice.maximumInstructionsBytes > 0
            && finiteChoice.maximumChoiceDescriptionBytes > 0
            && finiteChoice.maximumAggregateBytes > 0
    }
}

struct DecisionCapabilityRequirement: Equatable {
    let contextKind: DecisionServiceCapabilities.ContextKind
    let requiresConfidence: Bool
    let requiresProbabilities: Bool
    let requiresUsage: Bool

    static let textFiniteChoice = Self(
        contextKind: .text,
        requiresConfidence: false,
        requiresProbabilities: false,
        requiresUsage: false
    )
}

extension FiniteChoiceDecisionRequest {
    var aggregateUTF8Bytes: Int {
        textContext.utf8.count
            + question.name.utf8.count
            + question.instructions.utf8.count
            + question.choices.reduce(0) { $0 + $1.opaqueKey.utf8.count + $1.description.utf8.count }
    }
}

protocol DecisionService: Sendable {
    var id: DecisionServiceID { get }
    var displayName: String { get }
    var capabilities: DecisionServiceCapabilities { get }
